  case Suit::spades:   /* ... */ break;
}

class Suit {
  enum Inner { clubs_, diamonds_, hearts_, spades_ } v_;
  explicit Suit(Inner v) : v_(v) {}
public:
  static const Suit clubs, diamonds, hearts, spades;
  int toInt() const { return v_; }          // explicit, not implicit
};

const Suit Suit::clubs(Suit::clubs_);       // repeat for each member

